WITH filtered AS (SELECT id, product_id, quantity, unit_price, unit_price + quantity AS line_total FROM order_items WHERE product_id IS NOT NULL) SELECT id, product_id, quantity, unit_price, line_total, CUME_DIST() OVER (PARTITION BY product_id ORDER BY line_total DESC NULLS LAST) AS line_total_cume_dist, RANK() OVER (PARTITION BY product_id ORDER BY unit_price NULLS LAST) AS unit_price_rank FROM filtered;
